data class Expense(val category: String, val amount: Double)
fun List<Expense>.totalWhere(rule: (Expense) -> Boolean): Double =
    filter(rule).sumOf { it.amount }
fun main() {
    val items = listOf(Expense("Food", 5.0), Expense("Travel", 12.0))
    val travelTotal = items.totalWhere { it.category == "Travel" }
    println(travelTotal)
}
